def g(game_id,title,pmin,pmax,tmin,tmax,age,ratings,appeal,how,scenes,query,tags=""):
    d,s,l,c,e,co,b,cp,f,ch,lg,p,sp=[int(x) for x in ratings.split("")]
    steps=how.split("|")
    scene_list=scenes.split("|")
    return {
        "game_id":game_id,"title":title,"players_min":pmin,"players_max":pmax,
        "play_time_min":tmin,"play_time_max":tmax,"age":age,
        "difficulty":d,"strategy":s,"luck":l,"conversation":c,"excitement":e,
        "cooperation":co,"beginner":b,"couple":cp,"family":f,"children":ch,
        "large_group":lg,"party":p,"short_play":sp,
        "description":appeal,"appeal":appeal,"atmosphere":appeal,
        "how_to_play":steps,"recommended_scene":scene_list,
        "rakuten_query":query,"tags":[x for x in tags.split("|") if x],
    }

